        {
          "Name": "Targeting",
          "Parameters": {
            "Audience": {
              "Users": ["user1@company.com", "user2@company.com"],
              "Groups": [
                { "Name": "beta-testers", "RolloutPercentage": 100 },
                { "Name": "internal", "RolloutPercentage": 50 }
              ],
